#include <stdio.h>

int bowls[6] = {4, 8, 15, 16, 23, 42};

int main(void) {
    int want = 42;
    int tries = 0;
    for (int i = 0; i < 6; i++) {
        tries++;
        if (bowls[i] == want) {
            break;
        }
    }
    printf("%d\n", tries);
    return 0;
}

